'use strict';
let soundCatalog=[],soundCatalogReady=false,soundPreviewContext=null,soundPreviewSource=null,previewSoundId=null;
const soundLibraryBuffers=new Map();
let soundFavorites;try{soundFavorites=new Set(JSON.parse(localStorage.getItem('elleson-sound-favorites')||'[]'))}catch{soundFavorites=new Set()}
document.querySelector('.tabs').insertAdjacentHTML('beforeend','<button data-tab="sounds">Sounds</button>');
$('mediaTab').insertAdjacentHTML('afterend',`<div id="soundsTab" hidden><div class="eyebrow">SOUND LIBRARY</div><h3>Sound for your story.</h3><select id="soundCollection" aria-label="Sound collection"><option value="explainer">Explainer essentials</option><option value="legacy">Legacy game & UI</option><option value="all">Every collection</option></select><input id="soundSearch" type="search" placeholder="Search effects…" aria-label="Search sound effects"><select id="soundCategory" aria-label="Sound category"><option value="all">All sounds</option><option value="favorites">★ Favorites</option></select><div class="sound-library-meta"><span id="soundCount">Loading sounds…</span><span>CC0 · free to use</span></div><div id="soundCatalog"></div><button id="importOwnEffect">＋ Import your sound</button><details><summary>Sources & usage</summary><p class="note">Explainer essentials includes 11 transitions, notification and foley effects from AudioPapkin, SFXMint and other credited creators. The earlier 113 game/interface effects remain in the Legacy collection. All files are CC0; source and format details are included.</p><button id="soundCredits">View credits</button></details></div>`);
document.body.insertAdjacentHTML('beforeend','<dialog id="soundCreditsDialog"><h2>Sound library credits</h2><pre id="soundCreditsText"></pre><button id="closeSoundCredits">Close</button></dialog>');
document.querySelector('[data-tab="cast"]').textContent='Cast';
const tabBeforeSounds=tab;tab=function(name){tabBeforeSounds(name);$('soundsTab').hidden=name!=='sounds';if(name!=='sounds')stopSoundPreview()};document.querySelector('[data-tab="sounds"]').onclick=()=>tab('sounds');
function stopSoundPreview(){if(soundPreviewSource){try{soundPreviewSource.stop()}catch{}}soundPreviewSource=null;previewSoundId=null;if(soundCatalogReady)renderSoundCatalog()}
async function soundBuffer(item){let buffer=soundLibraryBuffers.get(item.id);if(buffer)return buffer;const r=await fetch(item.path);if(!r.ok)throw Error('Sound file unavailable.');const blob=await r.blob();buffer=await decodeFile(blob);soundLibraryBuffers.set(item.id,buffer);return buffer}
async function previewSound(item){if(previewSoundId===item.id)return stopSoundPreview();stopSoundPreview();stop();previewSoundId=item.id;renderSoundCatalog();try{const buffer=await soundBuffer(item);if(previewSoundId!==item.id)return;soundPreviewContext??=new AudioContext();await soundPreviewContext.resume();if(previewSoundId!==item.id)return;const source=soundPreviewContext.createBufferSource(),gain=soundPreviewContext.createGain();source.buffer=buffer;gain.gain.value=item.volume??.65;source.connect(gain).connect(soundPreviewContext.destination);soundPreviewSource=source;source.onended=()=>{if(soundPreviewSource===source){soundPreviewSource=null;previewSoundId=null;renderSoundCatalog()}};source.start()}catch(e){stopSoundPreview();toast(e.message)}}
async function addLibrarySound(item){if(recording)return;stopSoundPreview();stop();try{const r=await fetch(item.path);if(!r.ok)throw Error('Sound unavailable.');const blob=new Blob([await r.arrayBuffer()],{type:item.mime}),buffer=await soundBuffer(item);const start=Math.min(globalTime(),Math.max(0,totalDuration()-.01));const c={id:uid(),name:item.name,role:'effect',start,offset:0,duration:Math.min(buffer.duration,totalDuration()-start),sourceDuration:buffer.duration,volume:item.volume??.65,fadeIn:0,fadeOut:0,src:await dataURL(blob),sourceInfo:{author:item.author,license:item.license,sourceUrl:item.sourceUrl,asset:item.id}};tracks().push(c);audioBuffers.set(c.id,buffer);selectedAudio=c.id;selected=null;save();render();toast(item.name+' added at '+start.toFixed(2)+' s.');const clips=document.querySelectorAll('.timeline-clip.audio.active');clips[0]?.scrollIntoView({block:'nearest',inline:'nearest'})}catch(e){toast(e.message||'Could not add sound.')}}
function renderSoundCatalog(){const search=$('soundSearch').value.toLowerCase().trim(),category=$('soundCategory').value;const results=soundCatalog.filter(item=>soundCollectionIncludes(item)&&(category==='all'||category==='favorites'&&soundFavorites.has(item.id)||item.category===category)&&[item.name,item.category,...item.tags].join(' ').toLowerCase().includes(search));$('soundCount').textContent=results.length+' effects';const el=$('soundCatalog');el.replaceChildren();for(const item of results){const card=document.createElement('div');card.className='sound-card';const listen=document.createElement('button');listen.className='sound-listen';listen.textContent=previewSoundId===item.id?'■':'▶';listen.title='Preview '+item.name;listen.setAttribute('aria-label','Preview '+item.name);listen.onclick=()=>previewSound(item);const info=document.createElement('div');info.className='sound-info';const title=document.createElement('strong');title.textContent=item.name;const meta=document.createElement('small');meta.textContent=item.category+(item.duration?' · '+item.duration.toFixed(2)+'s':'');info.append(title,meta);if(item.waveform){const canvas=document.createElement('canvas');canvas.width=100;canvas.height=14;canvas.className='sound-mini-wave';const cx=canvas.getContext('2d');cx.strokeStyle='#789f93';cx.beginPath();item.waveform.forEach((v,i)=>{const x=i/item.waveform.length*100;cx.moveTo(x,7-v*7);cx.lineTo(x,7+v*7)});cx.stroke();info.append(canvas)}const favorite=document.createElement('button');favorite.className='sound-favorite';favorite.textContent=soundFavorites.has(item.id)?'★':'☆';favorite.title='Favorite '+item.name;favorite.onclick=()=>{soundFavorites.has(item.id)?soundFavorites.delete(item.id):soundFavorites.add(item.id);try{localStorage.setItem('elleson-sound-favorites',JSON.stringify([...soundFavorites]))}catch{}renderSoundCatalog()};const add=document.createElement('button');add.className='sound-add';add.textContent='＋';add.title='Add '+item.name+' at playhead';add.setAttribute('aria-label','Add '+item.name);add.onclick=()=>addLibrarySound(item);card.append(listen,info,favorite,add);el.append(card)}if(!results.length)el.innerHTML='<p class="note">'+(category==='favorites'?'Star sounds to keep your favorites here.':'No sounds match this search.')+'</p>'}
function soundCollectionIncludes(item){return $('soundCollection').value==='all'||(item.pack||'legacy')===$('soundCollection').value}
function renderSoundCategories(){const chosen=$('soundCategory').value;$('soundCategory').innerHTML='<option value="all">All sounds</option><option value="favorites">★ Favorites</option>';for(const category of [...new Set(soundCatalog.filter(soundCollectionIncludes).map(i=>i.category))].sort()){const opt=document.createElement('option');opt.value=category;opt.textContent=category;$('soundCategory').append(opt)}if([...$('soundCategory').options].some(o=>o.value===chosen))$('soundCategory').value=chosen;renderSoundCatalog()}
$('soundCollection').onchange=()=>{stopSoundPreview();renderSoundCategories()};$('soundSearch').oninput=renderSoundCatalog;$('soundCategory').onchange=renderSoundCatalog;$('importOwnEffect').onclick=()=>$('effectFile').click();$('effectFile').onchange=e=>{const files=[...e.target.files];e.target.value='';importSounds(files,'effect')};
$('soundCredits').onclick=async()=>{try{$('soundCreditsText').textContent=await(await fetch('sounds/CREDITS.md')).text();$('soundCreditsDialog').showModal()}catch{toast('Credits file unavailable.')}};$('closeSoundCredits').onclick=()=>$('soundCreditsDialog').close();
const playBeforeLibrary=play;play=function(){stopSoundPreview();return playBeforeLibrary()};$('play').onclick=play;const exportBeforeLibrary=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{stopSoundPreview();return exportBeforeLibrary()};
fetch('sounds/manifest.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(items=>{soundCatalog=items;soundCatalogReady=true;renderSoundCategories()}).catch(()=>$('soundCount').textContent='Sound library could not load.');
